DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.settle_daily_life(uuid)'::regprocedure) INTO def; def:=replace(def,'(auth.uid() IS DISTINCT FROM c.user_id AND current_user<>''postgres'')','auth.uid() IS DISTINCT FROM c.user_id'); EXECUTE def; SELECT pg_get_functiondef('public.start_life_activity(text,uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'a.start_time:=t; a.end_time:=t+r.duration_minutes*interval ''1 minute'';','IF a.type=''social'' THEN a.end_time:=t+(a.end_time-a.start_time); ELSE a.end_time:=t+r.duration_minutes*interval ''1 minute''; END IF; a.start_time:=t;'); def:=replace(def,'IF NOT FOUND OR _type=''course'' THEN','IF NOT FOUND OR _type IN(''course'',''social'') THEN'); EXECUTE def; END $$;
COMMENT ON FUNCTION public.settle_daily_life(uuid) IS 'Ownership is checked using the caller auth.uid even inside SECURITY DEFINER; no database-owner bypass.';